// @story:SCRUM-25
// @ac:1
// @design:D6
// @type:functional
// @technique:state-transition
// @llm-generated
test("AC-1 Correct current password and matching new password changes the password and shows confirmation", async ({ page }, testInfo) => {
  const changePasswordPage = new ChangePasswordPage(page);
  const currentPass = process.env["AQA_APP_PASS"]!;
  const newPass = "ChangedPass_SCRUM25_D6!";

  await test.step("Given I am logged in as a registered customer", async () => {
    const loginResponse = await page.request.post("/rest/user/login", {
      data: { email: process.env["AQA_APP_USER"], password: currentPass },
    });
    expect(loginResponse.status(), "Precondition: login must succeed (check AQA_APP_USER / AQA_APP_PASS)").toBe(200);
    const body = await loginResponse.json();
    const token = body?.authentication?.token;
    expect(token, "Precondition: login response must contain a token").toBeTruthy();
    await page.evaluate((t) => localStorage.setItem("token", t), token);
  });

  await test.step("When I navigate to \"/#/privacy-security/change-password\"", async () => {
    await changePasswordPage.goto();
  });

  await test.step("And I find the Current Password field and enter the current password", async () => {
    await changePasswordPage.currentPassword.fill(currentPass);
  });

  await test.step("And I find the New Password field and enter a valid new password", async () => {
    await changePasswordPage.newPassword.fill(newPass);
  });

  await test.step("And I find the Repeat New Password field and enter the same valid new password", async () => {
    await changePasswordPage.repeatNewPassword.fill(newPass);
  });

  await test.step("And I click the Change button", async () => {
    await changePasswordPage.buttonToConfirmTheChangeButton.click();
  });

  await test.step("Then the page displays \"Password successfully changed\"", async () => {
    await expect(changePasswordPage.page.getByText("Password successfully changed").first()).toBeVisible();
  });

  await test.step("And the password is restored to the original for subsequent tests", async () => {
    // Restore the original password so the dedicated test account remains usable
    const restoreResponse = await page.request.post("/rest/user/change-password", {
      params: { current: newPass, new: currentPass, repeat: currentPass },
    });
    expect(restoreResponse.status(), "Postcondition: password restore must succeed").toBe(200);
  });
});
